import{d as r,C as a,o as g,c as d,a3 as t,E as e,j as s,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第三十八章","description":"《正易心法》第三十八章——卦位生数，运以成数：生数一二三四五为阴阳之位（天道，有象无形），成数六七八九十为刚柔之德（地道，有形）；以成数运于生数之上，天地交感，吉凶叶应。","frontmatter":{"title":"正易心法·第三十八章","description":"《正易心法》第三十八章——卦位生数，运以成数：生数一二三四五为阴阳之位（天道，有象无形），成数六七八九十为刚柔之德（地道，有形）；以成数运于生数之上，天地交感，吉凶叶应。","category":"guide","aliases":["正易心法第三十八章","卦位生数运以成数","生成之数感应之道"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-38.md","filePath":"yijing/zheng-yi-xin-fa/chapter-38.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-38.md"},x=r({...c,setup(u){const i=[{id:"z38-01",label:"一、生数与成数",showLabel:!0,sentences:[["卦位",{text:"生数",glossary:"shengshu"},"，运以",{text:"成数",glossary:"chengshu"},"。生成之数，",{text:"感应之道",glossary:"ganyingZhidao"},"。"]],note:["卦的位置对应生数，用成数来运转；生数与成数，是天地感应之道。（**本章极短，却是全书少见的「枢纽章」**：**前面讲数是「是什么」，本章讲数是「怎么作用」——从数理过渡到感应。**「没有感应，数只是数；有了感应，数才能知吉凶。」）"]},{id:"z38-02",label:"二、天道与地道",showLabel:!0,sentences:[["生数，谓一二三四五，",{text:"阴阳之位",glossary:"yinyangZhiwei"},"也，天道也。成数，谓六七八九十，",{text:"刚柔之德",glossary:"gangrouZhide"},"也，地道也。"]],note:["生数，是一二三四五，是阴阳的位置，是天道；成数，是六七八九十，是刚柔的德性，是地道。（**这一对区分值得细读**：**阴阳＝气的方向**（升／降、聚／散），是**天道**的属性，无形只有位置；**刚柔＝物的质地**（硬／软、动／静），是**地道**的属性，有形有质感。**生数提供坐标，成数提供物质。**）"]},{id:"z38-03",label:"三、天地交感",showLabel:!0,sentences:[["以刚柔成数，而运于阴阳生数之上，然后天地",{text:"交感",glossary:"jiaogan"},"，吉凶",{text:"叶应",glossary:"xieying"},"。而天下之事，无能逃于其间矣。"]],note:["用刚柔的成数，在阴阳生数之上运行，然后天地交感，吉凶协同感应，天下的事没有能逃出其中的。（**这一步是本章的核心机制**：「成数在生数上运行」——**静的是坐标（位），动的是德（运），两相运合就是「交感」。** 与第三十七章的「孕于」同理：**不是并列对应，而是「运行于其上」——有先后、有主从。**）"]},{id:"z38-04",label:"四、无形与有形",showLabel:!0,sentences:[["阴阳之位，有",{text:"象无形",glossary:"xiangWuxing"},"，在天也。刚柔则形，而以其在地也。"]],note:["阴阳之位，有象无形，属于天；刚柔则成形，属于地。（**「有象无形」四字是全章的落点**：**生数是「位」——可以感知但不可触摸；成数是「物」——落到实处可见。** 原文「有所无形」当为「有象无形」之讹。）"]}],p=[{id:"shengshu",term:"生数",pinyin:"shēng shù",meaning:"一二三四五，阴阳之位，天道。有象无形，提供坐标。"},{id:"chengshu",term:"成数",pinyin:"chéng shù",meaning:"六七八九十，刚柔之德，地道。有形可见，提供物质与运行。"},{id:"ganyingZhidao",term:"感应之道",pinyin:"gǎn yìng zhī dào",meaning:"感而遂通之道。天地之间因数而感应，吉凶因此呼应。"},{id:"yinyangZhiwei",term:"阴阳之位",pinyin:"yīn yáng zhī wèi",meaning:"阴阳的位置。生数定位，是天道的坐标。"},{id:"gangrouZhide",term:"刚柔之德",pinyin:"gāng róu zhī dé",meaning:"刚柔的德性。成数显德，是地道的品质。"},{id:"jiaogan",term:"交感",pinyin:"jiāo gǎn",meaning:"天地相互感应。生数（天）与成数（地）相运合。"},{id:"xieying",term:"叶应",pinyin:"xié yìng",meaning:"协同感应。叶＝协。天地交感之后，吉凶自然呼应。"},{id:"xiangWuxing",term:"有象无形",pinyin:"yǒu xiàng wú xíng",meaning:"有气象但无实体。天道：可感知但不可触摸。原文作「有所无形」，当为「有象无形」。"}];return(b,n)=>{const l=a("DaoTextReading"),o=a("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t("",19)),e(l,{colophon:"卦位生数 · 运以成数 · 天地交感 · 感应之道",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三十八章原文",sections:i,glossary:p}),n[1]||(n[1]=s("blockquote",null,[s("p",null,"注：本页依所据底本录入。原文「有所无形」当为「有象无形」之讹，此处说明而不径改。")],-1)),n[2]||(n[2]=s("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),s("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(o,{items:[{term:"生数（天道）",pinyin:["shēng","shù"],meaning:"一二三四五，阴阳之位——有象无形，是天道的坐标。"},{term:"成数（地道）",pinyin:["chéng","shù"],meaning:"六七八九十，刚柔之德——刚柔则形，是地道的品质与运行。"},{term:"阴阳与刚柔",pinyin:["gāng","róu"],meaning:"阴阳＝气的方向（内在、无形）；刚柔＝物的质地（外在、有形）。麻衣强调此区分不可混。"},{term:"感应之道",pinyin:["gǎn","yìng"],meaning:"感而遂通之道。成数运于生数之上，天地交感，吉凶因此呼应。"},{term:"无能逃于其间",pinyin:["wú","néng"],meaning:"万事皆兼「位」（生数）与「运」（成数）两个维度——两者穷尽了「事」的所有可能。"}]}),n[3]||(n[3]=t("",23))])}}});export{m as __pageData,x as default};
